void Solver::bump_var(int var, double coeff) {
    // Use a non-linear bump: variables at higher decision levels get extra boost
    double level_bonus = (level[var] > 0) ? (1.0 + 0.1 * (level[var] & 7)) : 1.0;
    double effective_coeff = coeff * level_bonus;
    if ((activity[var] += var_inc * effective_coeff) > 1e100) {
        for (int i = 1; i <= vars; i++) activity[i] *= 1e-100;
        var_inc *= 1e-100;
    }
    if (vsids.inHeap(var)) vsids.update(var);
}
